(async () => {
  /* La sezione dell'ORA è già aperta da sé: cliccarla la CHIUDE. Apriamola
     solo se è chiusa, altrimenti la scena finisce su una riga chiusa — e
     misurava a seconda dell'ora del giorno in cui si lancia. */
  const sez = document.querySelector('#vista .rit-blocco[data-rit="checkin"]');
  if (!sez) throw new Error('manca la riga: checkin');
  if (!sez.classList.contains('aperto')) {
    sez.querySelector('.rit-riga').click();
    await new Promise((r) => setTimeout(r, 700));
  }
})()

