(async () => {
  /* la barra della ricerca compare da dieci cose in su, e la demo ne ha
     nove: due in più e c'è */
  LM.aggiungiBacklog('Prova per la ricerca uno', 'altro', true);
  LM.aggiungiBacklog('Prova per la ricerca due', 'altro', true);
  location.hash = '#/oggi';
  await new Promise((r) => setTimeout(r, 400));
  location.hash = '#/inbox';
  await new Promise((r) => setTimeout(r, 700));
  const t = document.querySelectorAll('#att-tabs button')[1];
  if (t) t.click();
  await new Promise((r) => setTimeout(r, 500));
  const i = document.getElementById('att-q');
  if (!i) throw new Error('manca il campo della ricerca');
  i.focus(); i.value = 'prova';
  i.dispatchEvent(new Event('input', { bubbles: true }));
  await new Promise((r) => setTimeout(r, 600));
})()

